import { addClassNamesToElement } from "@lexical/utils";
import type {
  DOMConversionMap,
  DOMConversionOutput,
  DOMExportOutput,
  EditorConfig,
  LexicalNode,
  LexicalUpdateJSON,
  NodeKey,
  SerializedElementNode,
  Spread,
} from "lexical";
import { ElementNode } from "lexical";

export type SerializedLayoutContainerNode = Spread<
  {
    templateColumns: string;
  },
  SerializedElementNode
>;

const convertLayoutContainerElement = (
  domNode: HTMLElement
): DOMConversionOutput | null => {
  const templateColumns = domNode.style.gridTemplateColumns;
  if (!templateColumns) {
    return null;
  }

  return {
    node: $createLayoutContainerNode(templateColumns),
  };
};

export class LayoutContainerNode extends ElementNode {
  __templateColumns: string;

  constructor(templateColumns: string, key?: NodeKey) {
    super(key);
    this.__templateColumns = templateColumns;
  }

  static getType(): string {
    return "layout-container";
  }

  static clone(node: LayoutContainerNode): LayoutContainerNode {
    return new LayoutContainerNode(node.__templateColumns, node.__key);
  }

  static importDOM(): DOMConversionMap | null {
    return {
      div: (domNode: HTMLElement) => {
        if (!Object.hasOwn(domNode.dataset, "lexicalLayoutContainer")) {
          return null;
        }

        return {
          conversion: convertLayoutContainerElement,
          priority: 2,
        };
      },
    };
  }

  static importJSON(
    serializedNode: SerializedLayoutContainerNode
  ): LayoutContainerNode {
    return $createLayoutContainerNode().updateFromJSON(serializedNode);
  }

  createDOM(config: EditorConfig): HTMLElement {
    const dom = document.createElement("div");
    dom.dataset.lexicalLayoutContainer = "true";
    dom.style.gridTemplateColumns = this.__templateColumns;

    if (typeof config.theme.layoutContainer === "string") {
      addClassNamesToElement(dom, config.theme.layoutContainer);
    }

    return dom;
  }

  updateDOM(prevNode: this, dom: HTMLElement): boolean {
    if (prevNode.__templateColumns !== this.__templateColumns) {
      dom.style.gridTemplateColumns = this.__templateColumns;
    }

    return false;
  }

  exportDOM(): DOMExportOutput {
    const element = document.createElement("div");
    element.dataset.lexicalLayoutContainer = "true";
    element.style.display = "grid";
    element.style.gap = "1rem";
    element.style.gridTemplateColumns = this.__templateColumns;

    return { element };
  }

  exportJSON(): SerializedLayoutContainerNode {
    return {
      ...super.exportJSON(),
      templateColumns: this.__templateColumns,
      type: "layout-container",
      version: 1,
    };
  }

  updateFromJSON(
    serializedNode: LexicalUpdateJSON<SerializedLayoutContainerNode>
  ): this {
    return super
      .updateFromJSON(serializedNode)
      .setTemplateColumns(serializedNode.templateColumns);
  }

  getTemplateColumns(): string {
    return this.getLatest().__templateColumns;
  }

  setTemplateColumns(templateColumns: string): this {
    const self = this.getWritable();
    self.__templateColumns = templateColumns;
    return self;
  }

  isShadowRoot(): boolean {
    return true;
  }

  canBeEmpty(): boolean {
    return false;
  }
}

export function $createLayoutContainerNode(
  templateColumns = ""
): LayoutContainerNode {
  return new LayoutContainerNode(templateColumns);
}

export function $isLayoutContainerNode(
  node: LexicalNode | null | undefined
): node is LayoutContainerNode {
  return node instanceof LayoutContainerNode;
}

import { addClassNamesToElement } from "@lexical/utils";
import type {
  DOMConversionMap,
  DOMConversionOutput,
  EditorConfig,
  LexicalNode,
  SerializedElementNode,
} from "lexical";
import { $isParagraphNode, ElementNode } from "lexical";

export type SerializedLayoutItemNode = SerializedElementNode;

const convertLayoutItemElement = (): DOMConversionOutput => ({
  node: $createLayoutItemNode(),
});

export function $isEmptyLayoutItemNode(node: LexicalNode): boolean {
  if (!$isLayoutItemNode(node) || node.getChildrenSize() !== 1) {
    return false;
  }

  const firstChild = node.getFirstChild();
  return $isParagraphNode(firstChild) && firstChild.isEmpty();
}

export class LayoutItemNode extends ElementNode {
  static getType(): string {
    return "layout-item";
  }

  static clone(node: LayoutItemNode): LayoutItemNode {
    return new LayoutItemNode(node.__key);
  }

  static importDOM(): DOMConversionMap | null {
    return {
      div: (domNode: HTMLElement) => {
        if (!Object.hasOwn(domNode.dataset, "lexicalLayoutItem")) {
          return null;
        }

        return {
          conversion: convertLayoutItemElement,
          priority: 2,
        };
      },
    };
  }

  static importJSON(serializedNode: SerializedLayoutItemNode): LayoutItemNode {
    return $createLayoutItemNode().updateFromJSON(serializedNode);
  }

  createDOM(config: EditorConfig): HTMLElement {
    const dom = document.createElement("div");
    dom.dataset.lexicalLayoutItem = "true";

    if (typeof config.theme.layoutItem === "string") {
      addClassNamesToElement(dom, config.theme.layoutItem);
    }

    return dom;
  }

  updateDOM(): boolean {
    return false;
  }

  collapseAtStart(): boolean {
    const parent = this.getParentOrThrow();

    if (
      this.is(parent.getFirstChild()) &&
      parent.getChildren().every($isEmptyLayoutItemNode)
    ) {
      parent.remove();
      return true;
    }

    return false;
  }

  isShadowRoot(): boolean {
    return true;
  }
}

export function $createLayoutItemNode(): LayoutItemNode {
  return new LayoutItemNode();
}

export function $isLayoutItemNode(
  node: LexicalNode | null | undefined
): node is LayoutItemNode {
  return node instanceof LayoutItemNode;
}

import type { NodeKey } from "lexical";
import { createCommand } from "lexical";

export interface InsertLayoutPayload {
  /**
   * When omitted or empty the plugin opens its own preset dialog instead of
   * applying a layout directly — the slash menu and toolbars dispatch the
   * bare command without owning any dialog UI.
   */
  targetNodeKey?: NodeKey;
  templateColumns?: string;
}

export const INSERT_LAYOUT_COMMAND = createCommand<InsertLayoutPayload>(
  "INSERT_LAYOUT_COMMAND"
);

export interface LayoutPreset {
  description: string;
  label: string;
  value: string;
}

export const DEFAULT_LAYOUT_TEMPLATE = "1fr 1fr";

export const LAYOUT_PRESETS: LayoutPreset[] = [
  {
    description: "Two equal columns",
    label: "2 columns (equal width)",
    value: "1fr 1fr",
  },
  {
    description: "Sidebar plus content",
    label: "2 columns (25% - 75%)",
    value: "1fr 3fr",
  },
  {
    description: "Three equal columns",
    label: "3 columns (equal width)",
    value: "1fr 1fr 1fr",
  },
  {
    description: "Three balanced columns",
    label: "3 columns (25% - 50% - 25%)",
    value: "1fr 2fr 1fr",
  },
  {
    description: "Four equal columns",
    label: "4 columns (equal width)",
    value: "1fr 1fr 1fr 1fr",
  },
];

import { PanelsTopLeftIcon } from "lucide-react";

import { LayoutContainerNode } from "../../core/nodes/layout/container-node";
import { LayoutItemNode } from "../../core/nodes/layout/item-node";
import type { ExtraEditorFeature } from "../../core/types";
import { INSERT_LAYOUT_COMMAND } from "./commands";
import { LayoutPlugin } from "./plugin";

/**
 * Installs the layout feature: the container/item nodes, the column preset
 * picker and the shared insert-menu entry. Ships as the `editor-layouts`
 * registry item.
 */
export const layoutFeature: ExtraEditorFeature = {
  id: "layout",
  nodes: [LayoutContainerNode, LayoutItemNode],
  plugin: LayoutPlugin,
  slashCommands: [
    {
      command: {
        description: "Multi-column content layout",
        icon: PanelsTopLeftIcon,
        id: "columns",
        keywords: ["columns", "layout", "grid", "multi-column"],
        label: "Columns",
      },
      run: (editor) => {
        editor.dispatchCommand(INSERT_LAYOUT_COMMAND, {});
      },
    },
  ],
};

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { $findMatchingParent, mergeRegister } from "@lexical/utils";
import {
  $createParagraphNode,
  $getNodeByKey,
  $getSelection,
  $isElementNode,
  $isParagraphNode,
  $isRangeSelection,
  $isTextNode,
  COMMAND_PRIORITY_EDITOR,
  COMMAND_PRIORITY_HIGH,
  COMMAND_PRIORITY_LOW,
  KEY_ARROW_DOWN_COMMAND,
  KEY_ARROW_LEFT_COMMAND,
  KEY_ARROW_RIGHT_COMMAND,
  KEY_ARROW_UP_COMMAND,
} from "lexical";
import { useEffect, useState } from "react";

import {
  $isLayoutContainerNode,
  LayoutContainerNode,
} from "../../core/nodes/layout/container-node";
import {
  $createLayoutItemNode,
  $isLayoutItemNode,
  LayoutItemNode,
} from "../../core/nodes/layout/item-node";
import { INSERT_LAYOUT_COMMAND } from "./commands";
import { LayoutPresetDialog } from "./preset-dialog";
import { applyLayoutPreset, insertLayoutPreset } from "./utils";

const EMPTY_DIALOG_STATE = {
  open: false,
  pendingTargetKey: null as string | null,
};

const shouldInsertParagraphBeforeLayout = (): LayoutContainerNode | null => {
  const selection = $getSelection();
  if (
    !(
      $isRangeSelection(selection) &&
      selection.isCollapsed() &&
      selection.anchor.offset === 0
    )
  ) {
    return null;
  }

  const container = $findMatchingParent(
    selection.anchor.getNode(),
    $isLayoutContainerNode
  );
  if (!$isLayoutContainerNode(container)) {
    return null;
  }

  const parent = container.getParent();
  if (
    parent &&
    parent.getFirstChild() === container &&
    selection.anchor.key === container.getFirstDescendant()?.getKey()
  ) {
    return container;
  }

  return null;
};

const shouldInsertParagraphAfterLayout = (): LayoutContainerNode | null => {
  const selection = $getSelection();
  if (!($isRangeSelection(selection) && selection.isCollapsed())) {
    return null;
  }

  const container = $findMatchingParent(
    selection.anchor.getNode(),
    $isLayoutContainerNode
  );
  if (!$isLayoutContainerNode(container)) {
    return null;
  }

  const parent = container.getParent();
  const lastDescendant = container.getLastDescendant();
  if (
    parent &&
    parent.getLastChild() === container &&
    lastDescendant &&
    selection.anchor.key === lastDescendant.getKey() &&
    selection.anchor.offset === lastDescendant.getTextContentSize()
  ) {
    return container;
  }

  return null;
};

export function LayoutPlugin() {
  const [editor] = useLexicalComposerContext();
  const [dialogState, setDialogState] = useState(EMPTY_DIALOG_STATE);

  useEffect(() => {
    if (!editor.hasNodes([LayoutContainerNode, LayoutItemNode])) {
      return;
    }

    const handleEscapeBefore = () => {
      const container = shouldInsertParagraphBeforeLayout();
      if (!container) {
        return false;
      }
      const paragraph = $createParagraphNode();
      container.insertBefore(paragraph);
      paragraph.select();
      return true;
    };

    const handleEscapeAfter = () => {
      const container = shouldInsertParagraphAfterLayout();
      if (!container) {
        return false;
      }
      const paragraph = $createParagraphNode();
      container.insertAfter(paragraph);
      paragraph.select();
      return true;
    };

    return mergeRegister(
      editor.registerNodeTransform(LayoutItemNode, (node) => {
        const parent = node.getParent();
        if (!$isLayoutContainerNode(parent)) {
          for (const child of node.getChildren()) {
            node.insertBefore(child);
          }
          node.remove();
          return;
        }
        if (node.getChildrenSize() === 0) {
          node.append($createParagraphNode());
        }
      }),
      editor.registerNodeTransform(LayoutContainerNode, (node) => {
        const children = node.getChildren();
        if (children.length === 0) {
          node.remove();
          return;
        }
        for (const child of children) {
          if (!$isLayoutItemNode(child)) {
            const item = $createLayoutItemNode();
            child.replace(item);
            if ($isElementNode(child) && !child.isInline()) {
              item.append(child);
            } else {
              const paragraph = $createParagraphNode();
              paragraph.append(child);
              item.append(paragraph);
            }
          }
        }
      }),
      editor.registerCommand(
        KEY_ARROW_UP_COMMAND,
        handleEscapeBefore,
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        KEY_ARROW_LEFT_COMMAND,
        handleEscapeBefore,
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        KEY_ARROW_DOWN_COMMAND,
        handleEscapeAfter,
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        KEY_ARROW_RIGHT_COMMAND,
        handleEscapeAfter,
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        INSERT_LAYOUT_COMMAND,
        ({ targetNodeKey, templateColumns }) => {
          if (!templateColumns) {
            return false;
          }

          if (targetNodeKey) {
            const targetNode = $getNodeByKey(targetNodeKey);
            if (!$isElementNode(targetNode)) {
              return false;
            }

            applyLayoutPreset(targetNode, templateColumns);
            return true;
          }

          const selection = $getSelection();
          if ($isRangeSelection(selection)) {
            const targetElement = selection.anchor
              .getNode()
              .getTopLevelElement();
            if (
              targetElement &&
              $isParagraphNode(targetElement) &&
              targetElement.getTextContent().trim().length === 0
            ) {
              applyLayoutPreset(targetElement, templateColumns);
              return true;
            }
          }

          insertLayoutPreset(templateColumns);
          return true;
        },
        COMMAND_PRIORITY_EDITOR
      ),
      // Incomplete payloads (no template) mean "open the preset picker".
      editor.registerCommand(
        INSERT_LAYOUT_COMMAND,
        (payload) => {
          if (payload.templateColumns) {
            return false;
          }

          let targetNodeKey: string | null = payload.targetNodeKey ?? null;

          if (!targetNodeKey) {
            editor.getEditorState().read(() => {
              const selection = $getSelection();
              if (!$isRangeSelection(selection)) {
                return;
              }
              const node = selection.anchor.getNode();
              const topLevel = node.getTopLevelElement();
              if (
                topLevel &&
                $isParagraphNode(topLevel) &&
                topLevel.getTextContent().trim().length === 0
              ) {
                targetNodeKey = topLevel.getKey();
              } else if (
                $isTextNode(node) &&
                node.getTextContent().trim().startsWith("/")
              ) {
                targetNodeKey = topLevel?.getKey() ?? null;
              }
            });
          }

          setDialogState({
            ...EMPTY_DIALOG_STATE,
            open: true,
            pendingTargetKey: targetNodeKey,
          });
          return true;
        },
        COMMAND_PRIORITY_HIGH
      )
    );
  }, [editor]);

  const closeDialog = () => {
    setDialogState(EMPTY_DIALOG_STATE);
  };

  const handleSelectPreset = (templateColumns: string) => {
    editor.dispatchCommand(INSERT_LAYOUT_COMMAND, {
      targetNodeKey: dialogState.pendingTargetKey ?? undefined,
      templateColumns,
    });
    closeDialog();
  };

  return (
    <LayoutPresetDialog
      onCancel={closeDialog}
      onOpenChange={(open) => {
        if (!open) {
          closeDialog();
        }
      }}
      onSelectPreset={handleSelectPreset}
      open={dialogState.open}
    />
  );
}

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { ScrollArea } from "@/components/ui/scroll-area";

import { LAYOUT_PRESETS } from "./constants";
import { getLayoutColumnCount } from "./utils";

function LayoutPresetPreview({ templateColumns }: { templateColumns: string }) {
  const columnCount = getLayoutColumnCount(templateColumns);

  return (
    <span className="editor-layout-preview block h-14 w-full">
      <span
        className="grid h-full gap-2"
        style={{ gridTemplateColumns: templateColumns }}
      >
        {Array.from({ length: columnCount }, (_, index) => (
          <span
            className="editor-layout-preview-cell block shadow-xs"
            key={`${templateColumns}-${index}`}
          />
        ))}
      </span>
    </span>
  );
}

interface LayoutPresetDialogProps {
  onCancel: () => void;
  onOpenChange: (open: boolean) => void;
  onSelectPreset: (templateColumns: string) => void;
  open: boolean;
}

export function LayoutPresetDialog({
  onCancel,
  onOpenChange,
  onSelectPreset,
  open,
}: LayoutPresetDialogProps) {
  return (
    <Dialog onOpenChange={onOpenChange} open={open}>
      <DialogContent
        className="flex max-h-[calc(100vh-2rem)] flex-col gap-0 overflow-hidden p-0 sm:max-w-2xl"
        showCloseButton
      >
        <DialogHeader className="px-4 pt-4 pb-0 sm:px-6 sm:pt-6">
          <DialogTitle>Choose column layout</DialogTitle>
          <DialogDescription>Select a column layout preset.</DialogDescription>
        </DialogHeader>

        <div className="max-h-[min(70vh,34rem)] min-h-0 flex-1 overflow-hidden">
          <ScrollArea className="h-full">
            <div className="grid gap-3 px-4 py-4 sm:grid-cols-2 sm:px-6">
              {LAYOUT_PRESETS.map((preset) => (
                <Button
                  className="editor-layout-option h-auto min-h-32 justify-start text-left hover:bg-muted/60"
                  key={preset.value}
                  onClick={() => onSelectPreset(preset.value)}
                  type="button"
                  variant="ghost"
                >
                  <span className="flex w-full flex-col items-start gap-2">
                    <LayoutPresetPreview templateColumns={preset.value} />
                    <span className="flex flex-col items-start gap-1">
                      <span className="text-sm font-medium text-foreground">
                        {preset.label}
                      </span>
                      <span className="text-xs text-muted-foreground">
                        {preset.description}
                      </span>
                      <span className="font-mono text-xs text-muted-foreground/80">
                        {preset.value}
                      </span>
                    </span>
                  </span>
                </Button>
              ))}
            </div>
          </ScrollArea>
        </div>

        <DialogFooter
          className="m-0 shrink-0 px-4 py-3 sm:px-6"
          showCloseButton={false}
        >
          <Button onClick={onCancel} type="button" variant="outline">
            Cancel
          </Button>
          <Button
            onClick={() =>
              onSelectPreset(LAYOUT_PRESETS[0]?.value ?? "1fr 1fr")
            }
            type="button"
          >
            Use default
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { $insertNodeToNearestRoot } from "@lexical/utils";
import { $createParagraphNode } from "lexical";
import type { ElementNode } from "lexical";

import { $createLayoutContainerNode } from "../../core/nodes/layout/container-node";
import { $createLayoutItemNode } from "../../core/nodes/layout/item-node";

const REPEAT_PREFIX_PATTERN = /^repeat\(\s*(?<count>\d+)\s*,/iu;

const readBalancedParensEnd = (value: string, openIndex: number): number => {
  let depth = 0;
  for (let index = openIndex; index < value.length; index += 1) {
    const char = value[index];
    if (char === "(") {
      depth += 1;
    } else if (char === ")") {
      depth -= 1;
      if (depth === 0) {
        return index;
      }
    }
  }
  return value.length - 1;
};

export const getLayoutColumnCount = (templateColumns: string): number => {
  const trimmed = templateColumns.trim();
  if (!trimmed) {
    return 1;
  }

  let count = 0;
  let index = 0;

  while (index < trimmed.length) {
    while (index < trimmed.length && /\s/u.test(trimmed[index])) {
      index += 1;
    }
    if (index >= trimmed.length) {
      break;
    }

    const slice = trimmed.slice(index);
    const repeatMatch = REPEAT_PREFIX_PATTERN.exec(slice);
    if (repeatMatch) {
      const repeatCount = Math.trunc(Number(repeatMatch.groups?.count ?? "0"));
      if (Number.isFinite(repeatCount) && repeatCount > 0) {
        count += repeatCount;
      }
      const openIndex = trimmed.indexOf("(", index);
      index = readBalancedParensEnd(trimmed, openIndex) + 1;
      continue;
    }

    // Consume one top-level track token (respecting nested parentheses such as minmax(0, 1fr)).
    let depth = 0;
    while (index < trimmed.length) {
      const char = trimmed[index];
      if (char === "(") {
        depth += 1;
      } else if (char === ")") {
        depth = Math.max(0, depth - 1);
      } else if (depth === 0 && /\s/u.test(char)) {
        break;
      }
      index += 1;
    }
    count += 1;
  }

  return Math.max(1, count);
};

export const createLayoutContainer = (templateColumns: string) => {
  const layoutContainer = $createLayoutContainerNode(templateColumns);
  const columnCount = getLayoutColumnCount(templateColumns);
  let firstParagraph: ReturnType<typeof $createParagraphNode> | null = null;

  for (let index = 0; index < columnCount; index += 1) {
    const layoutItem = $createLayoutItemNode();
    const paragraph = $createParagraphNode();

    if (firstParagraph === null) {
      firstParagraph = paragraph;
    }

    layoutItem.append(paragraph);
    layoutContainer.append(layoutItem);
  }

  return { firstParagraph, layoutContainer };
};

export const applyLayoutPreset = (
  targetElement: ElementNode,
  templateColumns: string
) => {
  const { firstParagraph, layoutContainer } =
    createLayoutContainer(templateColumns);

  targetElement.replace(layoutContainer);
  if (!layoutContainer.getNextSibling()) {
    layoutContainer.insertAfter($createParagraphNode());
  }
  firstParagraph?.selectEnd();
};

export const insertLayoutPreset = (templateColumns: string) => {
  const { firstParagraph, layoutContainer } =
    createLayoutContainer(templateColumns);

  $insertNodeToNearestRoot(layoutContainer);
  if (!layoutContainer.getNextSibling()) {
    layoutContainer.insertAfter($createParagraphNode());
  }
  firstParagraph?.selectEnd();
};
